mapper.select:
SELECT s.id, s.layout_version_id, s.parent_simulation_id, s.created_by, s.title, s.status, s.created_at, so.total_people, (CASE WHEN EXISTS (SELECT 1 FROM layout_search_candidates WHERE prepared_simulation_id = s.id) OR EXISTS (SELECT 1 FROM proposal_simulations WHERE simulation_id = s.id) THEN TRUE ELSE FALSE END) AS is_improvement FROM simulations s JOIN simulation_options so ON so.simulation_id = s.id WHERE s.layout_version_id = #{layoutVersionId}
AND s.created_by = #{createdBy}
ORDER BY s.created_at DESC, s.id DESC

SELECT s.id, s.layout_version_id, s.parent_simulation_id, s.created_by, s.title, s.status, s.created_at, s.requested_at, s.started_at, s.finished_at, so.total_people, l.id AS layout_id, l.title AS layout_title, lv.version AS layout_version_number, sr.termination_reason, (CASE WHEN EXISTS (SELECT 1 FROM layout_search_candidates WHERE prepared_simulation_id = s.id) OR EXISTS (SELECT 1 FROM proposal_simulations WHERE simulation_id = s.id) THEN TRUE ELSE FALSE END) AS is_improvement, (CASE WHEN EXISTS (SELECT 1 FROM layout_searches WHERE baseline_simulation_id = s.id) THEN TRUE ELSE FALSE END) AS has_layout_search FROM simulations s LEFT JOIN simulation_options so ON so.simulation_id = s.id LEFT JOIN layout_versions lv ON lv.id = s.layout_version_id LEFT JOIN layouts l ON l.id = lv.layout_id LEFT JOIN simulation_results sr ON sr.simulation_id = s.id
AND s.created_by = #{createdBy}
AND s.title LIKE CONCAT('%', #{query}, '%')
AND NOT EXISTS (SELECT 1 FROM layout_search_candidates WHERE prepared_simulation_id = s.id)
ORDER BY s.created_at DESC, s.id DESC LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM simulations s
WHERE s.created_by = #{createdBy}
  AND s.status = 'COMPLETED'
  AND s.finished_at >= #{weekStart}

SELECT agent_positions
FROM simulation_initial_states
WHERE simulation_id = #{simulationId}

SELECT t.frame_data
FROM timelines t
JOIN simulation_results sr ON sr.id = t.simulation_result_id
WHERE sr.simulation_id = #{simulationId}
  AND t.chunk_sequence = #{chunkSequence}

SELECT h.density_data
FROM heatmaps h
JOIN simulation_results sr ON sr.id = h.simulation_result_id
WHERE sr.simulation_id = #{simulationId}
  AND h.chunk_sequence = #{chunkSequence}

mapper.update:
UPDATE simulation_options
SET total_people = #{totalPeople},
    walking_speed = #{walkingSpeed},
    reaction_time = 0.5000,
    initial_response_time_std_dev = #{initialResponseTimeStdDev}
WHERE simulation_id = #{simulationId}

UPDATE simulations
SET title = #{title}
WHERE id = #{simulationId}

UPDATE simulation_options
SET model_profile = #{modelProfile},
    routing_profile = #{routingProfile}
WHERE simulation_id = #{simulationId}

UPDATE simulation_initial_states
SET agent_positions = CAST(#{agentPositions} AS JSON)
WHERE simulation_id = #{simulationId}

mapper.select:
SELECT COUNT(*)
FROM simulations
WHERE parent_simulation_id = #{simulationId}
